import{I as o,o as e,c as r,b6 as s,b0 as l,ih as p,ii as m,ij as c,ik as n,il as g,im as d,io as h,ip as _,iq as u,ir as F,is as f,it as q,iu as b,iv as A,iw as k,ix as M,iy as P,iz as E,iA as S,iB as G,iC as x,iD as B,iE as C,iF as I,iG as y,iH as D,iI as L,iJ as v,iK as T,iL as J,iM as N,iN as R,iO as H,J as V,k as w}from"./chunks/framework.BUXTSoD9.js";import{r as U}from"./chunks/relatedArticles.DIHQAH-1.js";const Z=JSON.parse('{"title":"مقدمة في Figma و MasterGo","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/frontend/figma-mastergo/index.md","filePath":"ar-sa/stage-2/frontend/figma-mastergo/index.md"}'),z={name:"ar-sa/stage-2/frontend/figma-mastergo/index.md"},Q=Object.assign(z,{setup(O){const i=U["ar-sa/stage-2/frontend/figma-mastergo"]??[];return(j,a)=>{const t=o("RelatedArticlesSection");return e(),r("div",null,[a[0]||(a[0]=s('<h1 id="مقدمة-في-figma-و-mastergo" tabindex="-1">مقدمة في Figma و MasterGo <a class="header-anchor" href="#مقدمة-في-figma-و-mastergo" aria-label="Permalink to “مقدمة في Figma و MasterGo”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">🎯 السؤال الجوهري</p><p><strong>كيف تبدأ من الصفر باستخدام أدوات التصميم الحديثة لإنشاء نماذج أولية لصفحات الويب؟</strong></p></div><hr><h2 id="_1-لماذا-نحتاج-إلى-تعلم-أدوات-تصميم-الواجهات-الأمامية؟" tabindex="-1">1. لماذا نحتاج إلى تعلم أدوات تصميم الواجهات الأمامية؟ <a class="header-anchor" href="#_1-لماذا-نحتاج-إلى-تعلم-أدوات-تصميم-الواجهات-الأمامية؟" aria-label="Permalink to “1. لماذا نحتاج إلى تعلم أدوات تصميم الواجهات الأمامية؟”">​</a></h2><p>قبل البدء، نحتاج إلى فهم سؤال: لماذا نحتاج إلى تعلم &quot;أدوات تصميم الواجهات الأمامية&quot;؟ أليس من الممكن بناء الصفحات مباشرة بكتابة كود HTML/CSS؟ هل حقًا من الضروري تعلم برنامج وتقنية إضافية؟</p><p>في الواقع، تشغيل الصفحة وتصميم المنتج بشكل جيد هما مفهومان مختلفان تمامًا. الكود يهتم فقط بكيفية العرض في المتصفح وكيفية العمل على الأجهزة المختلفة؛ أدوات تصميم الواجهات الأمامية تحل مشكلة توزيع المعلومات - كيفية ترتيب التفاعلات الأمامية، كيفية الانتقال بين الصفحات المختلفة، وكيفية توزيع الأولويات البصرية. يكفي إنشاء لوحة عمل في أداة التصميم لمقارنة وتحديد التخطيط والتسلسل الهرمي للمعلومات وطرق التفاعل على شاشة واحدة، واختيار أفضل طريقة عرض.</p><p>إذا بدأت مباشرة في كتابة الكود أو استخدام AI لإنشاء صفحات واجهة أمامية كاملة، فعادةً ما تكون تجربة المستخدم غير جيدة. المنتجات الدقيقة تأخذ في الاعتبار راحة تفاعل المستخدم مع الواجهة الأمامية، وتوزيع المحتوى الذي تريد كل صفحة نقله، وتبدأ من منظور المستخدم في ترتيب صفحات الواجهة الأمامية أولاً، ثم تحويلها إلى كود أو إنشائها.</p><p>بالإضافة إلى ذلك، من منظور التعاون الجماعي، أدوات تصميم الواجهات الأمامية تقلل أيضًا من تكلفة التعاون بين الأطراف المتعددة: لم يعد المصممون ومديرو المنتجات والمطورون ينظرون كل منهم إلى صورة في خياله أو وصف كود مجرد، بل يدعم التعاون المتزامن بين عدة أشخاص، ويمكن للجميع مناقشة إدارة الإصدارات وتغييرات المتطلبات وملاحظات حول لوحة عمل واحدة قابلة للعرض والتعليق والتكرار. علاوة على ذلك، لم تعد أدوات تصميم الواجهات الأمامية الحديثة مجرد برامج رسم، بل تنشئ جزءًا من الكود بنقرة واحدة وتدير أنظمة التصميم ومكتبات المكونات. أدوات التصميم في العصر الجديد قادرة على أتمتة أو تجميع الكثير من العمل اليدوي المتكرر (المحاذاة، التعليقات، التصدير، تعديل الأنماط)، مما يعزز بشكل كبير كفاءة تطوير تصميم الصفحات.</p><p><img src="'+l+'" alt=""></p><h3 id="_1-1-تطور-أدوات-تصميم-الواجهات-الأمامية" tabindex="-1">1.1 تطور أدوات تصميم الواجهات الأمامية <a class="header-anchor" href="#_1-1-تطور-أدوات-تصميم-الواجهات-الأمامية" aria-label="Permalink to “1.1 تطور أدوات تصميم الواجهات الأمامية”">​</a></h3><p>على مر الزمن، تطورت ما يسمى بأدوات تصميم الواجهات الأمامية باستمرار. من عصر Photoshop في التسعينيات الذي ركز على تحرير الصور النقطية المحلية، إلى سير العمل المتجه والمكونات الذي جلبه Sketch حوالي عام 2010، ثم نقل Figma التعاون إلى السحابة بالكامل بعد عام 2016، وانتقلت فرق التصميم من العمل الفردي إلى التعاون المتزامن بين عدة أشخاص. بحلول عام 2025، أصبح AI مدمجًا فعليًا في هذه الأدوات: من &quot;إنشاء مسودة صفحة بناءً على جملة واحدة&quot; إلى &quot;تحويل التصميم مباشرة إلى هيكل واجهة أمامية قابل للتشغيل&quot;، أصبح &quot;التصميم ككود&quot; و&quot;الإبداع المشترك بين الإنسان والآلة&quot; مفاهيم تتحول إلى إنتاجية قابلة للاستخدام.</p><p>في هذا القسم، سنقدم أداتين من أكثر أدوات تصميم الواجهات الأمامية الحديثة تمثيلاً: Figma و MasterGo. من ناحية، كلاهما يغطي القدرات الأساسية التي يحتاجها تصميم UI/UX الحديث (التحرير المتجه، نظام المكونات، التخطيط التلقائي، تسليم الكود، إلخ)، ويمكنهما دعمك لإكمال الحلقة الكاملة من الإطار السلكي إلى الدقة العالية إلى التسليم للتطوير؛ من ناحية أخرى، أضافت كلتا الأداتين ميزات AI عملية بعد عام 2025، لمساعدتك في تحويل التصميم إلى برنامج قابل للتشغيل حقًا مع الحفاظ على النموذج الأولي دون تغيير.</p><h2 id="_1-2-رحلة-الميلاد" tabindex="-1">1.2 رحلة الميلاد <a class="header-anchor" href="#_1-2-رحلة-الميلاد" aria-label="Permalink to “1.2 رحلة الميلاد”">​</a></h2><p><img src="'+p+'" alt=""></p><p>في العصر الذي لم تكن فيه أدوات تصميم الواجهات الأمامية المخصصة قد ظهرت بعد، كان برنامج تصميم &quot;شامل&quot; مثل Photoshop يتولى معظم أعمال التصميم البصري لصناعة تصميم الواجهات بالكامل لفترة طويلة. كان المصممون يكملون التصميم البصري العام للصفحة من خلال تراكب الطبقات محليًا، ويسلمون ملف المصدر .psd الكبير الحجم في النهاية إلى مهندس الواجهة الأمامية - ويجب على الواجهة الأمامية إكمال ثلاث مهام يدوية شاقة وحاسمة يدويًا لاستعادة التصميم بدقة:</p><p>أولاً &quot;تقطيع الصور&quot;: يجب استخراج العناصر المرئية المستقلة مثل الأزرار والأيقونات والشعارات ووحدات الخلفية واحدة تلو الأخرى من بنية الطبقات المتعددة لملف .psd، ثم تصديرها بتنسيقات صور يمكن تحميلها مباشرة على الويب مثل PNG وJPG (بعد كل شيء، لا يمكن للمتصفح التعرف مباشرة على معلومات طبقات PSD، ويعتمد على هذه الصور المقطعة لعرض التفاصيل)؛</p><p><img src="'+m+'" alt=""></p><p>ثانياً &quot;قياس الأبعاد&quot;: يجب استخدام أداة القياس المدمجة في البرنامج لتأكيد عرض وارتفاع كل عنصر، والمسافات بين الوحدات المختلفة (margin/padding) وغيرها من البيانات واحدة تلو الأخرى، لضمان دقة جميع الأبعاد إلى بكسل؛</p><p><img src="'+c+'" alt=""></p><p>ثالثاً &quot;استخراج التعليقات التوضيحية&quot;: يجب استخراج المعلمات &quot;غير المرئية ولكن الضرورية&quot; من التصميم - مثل حجم الخط ووزن الخط وارتفاع السطر للنص، وقيم RGB أو HEX لكل كتلة ملونة، أي ما يعادل استخراج &quot;مواصفات التصميم&quot; التي لم يكتبها المصمم على الورقة يدويًا.</p><p><img src="'+n+'" alt=""></p><p>بعد ذلك، تبدأ مرحلة تنفيذ الواجهة الأمامية حقًا. سواء تم استخدام HTML/CSS/JS الأصلي أو أطر عمل مثل Vue و React، فإن العملية الأساسية هي نفسها. تستخدم الواجهة الأمامية &quot;الحاوية كحامل أساسي&quot;، وتعيد بناء هيكل الصفحة وفقًا للتسلسل الهرمي ودلالات كل وحدة في التصميم. الحاوية هنا تشير إلى وحدة ذات حدود تخطيط واضحة، مخصصة لحمل وتنظيم العناصر الفرعية. لا تعرض المحتوى المباشر بنفسها، بل من خلال قواعد مثل Flex وGrid، تحدد نطاق ترتيب العناصر الداخلية. و&quot;الكتل الهيكلية&quot; (مثل شريط التنقل العلوي، الشريط الجانبي، منطقة قائمة المقالات، تذييل الصفحة، إلخ من المناطق الوظيفية/المحتوية التي يمكن تمييزها بصريًا) تعتمد على الحاويات؛ داخل كل كتلة هيكلية، ستكون هناك حاويات أصغر متداخلة لتنظيم العناصر، مثل عنصر قائمة مقالات واحد ستتحكم فيه &quot;حاوية عنصر القائمة&quot; في الهامش الداخلي والتخطيط العام، ثم تغلف العنوان والملخص والوقت وأيقونة الغلاف والتفاصيل الأخرى.</p><p><img src="'+g+'" alt=""></p><p>في أطر العمل الأمامية الحديثة، يتم عادةً تنفيذ هذه &quot;الكتل الهيكلية (والحاويات والعناصر المرتبطة بها)&quot; كـ &quot;مكونات&quot;. يمكن فهم المكونات ببساطة على أنها: وحدات واجهة قابلة لإعادة الاستخدام ذات حدود واضحة، تدمج تخطيط الحاوية والمنطق، وتحتوي على حاويات تتحكم في المظهر والترتيب (مثل &quot;مكون الزر&quot; يستخدم حاوية لتحديد العرض والارتفاع والحدود المستديرة، و&quot;مكون بطاقة المقالة&quot; يستخدم حاوية لتنظيم موضع العنوان والغلاف)، كما تغلف المنطق التفاعلي. الأجزاء المتكررة الظهور والمتسقة الشكل في التصميم (مثل الأزرار ذات النمط الموحد، بطاقات المقالات المستخدمة بشكل متكرر) سيتم تجريدها في الكود كمكونات: يمكن إعادة استخدامها في صفحات/سيناريوهات مختلفة لتقليل التطوير المتكرر، ويمكن أيضًا من خلال قواعد الحاويات الموحدة للمكونات ضمان اتساق التخطيط والنمط في جميع أماكن إعادة الاستخدام.</p><p>بعد ذلك، تستخدم الواجهة الأمامية نظام الأنماط لاستعادة المظهر والتخطيط. موارد PNG/JPG وغيرها التي تم تصديرها في مرحلة تقطيع الصور ستتم إضافتها كـ <code>&lt;img&gt;</code> أو صور خلفية داخل المكونات أو الكتل الهيكلية، أو يتم استيرادها وفقًا لطريقة الموارد الثابتة الموصى بها من كل إطار عمل؛ البيانات المحددة للعرض والارتفاع والمسافات وارتفاع السطر التي تم الحصول عليها في مرحلة قياس الأبعاد ستتحول إلى خصائص أنماط مثل <code>width</code> و <code>height</code> و <code>margin</code> و <code>padding</code> و <code>line-height</code> وتُطبق على المكونات أو الكتل الهيكلية المقابلة؛ الألوان والخطوط والظلال والحدود المستديرة وحالات hover/active وغيرها التي تم تنظيمها في مرحلة استخراج التعليقات ستُطبق على <code>color</code> و <code>font-family</code> و <code>font-size</code> و <code>box-shadow</code> و <code>border-radius</code> والفئات الزائفة أو فئات الحالة في حلول محددة مثل CSS و CSS Modules و CSS-in-JS و Tailwind. في هذا الوقت، توفر تقطيع الصور والأبعاد والتعليقات مجموعة من المعلمات البصرية الدقيقة، بينما توفر المكونات والكتل الهيكلية وحدات تنظيم الكود لحمل هذه المعلمات، والاثنان معًا يشكلان تنفيذ واجهة قابل للصيانة وإعادة الاستخدام.</p><p><img src="'+d+'" alt=""></p><p>لكن النموذج المتمحور حول الملفات المحلية بطبيعته غير فعال. تُنقل الإصدارات عبر البريد الإلكتروني وأقراص الشبكة، ويسهل الخلط بين المسودات الجديدة والقديمة، ويعتمد التصميم والتطوير بشكل كبير على طرق التفاعل المعقدة المذكورة أعلاه، وتكلفة التعاون واحتمال الأخطاء ليستا منخفضين.</p><p>بعد صعود الإنترنت المحمول، زادت متطلبات تعقيد الواجهة وسرعة التكرار بسرعة، وأصبح &quot;الكبير والشامل&quot; في Photoshop تدريجيًا ثقيلًا. في هذه المرحلة، ظهر Sketch. ركز Sketch على تصميم UI نفسه، وتخلص من معظم الأعباء المتعلقة بالمعالجة البصرية اللاحقة؛ استخدم Symbols لجعل العناصر عالية إعادة الاستخدام مثل الأزرار والتنقل ومربعات الإدخال مكونات، تعديل واحد يمكن أن يتزامن عالميًا؛ مع أدوات مثل Zeplin، أنشأ تلقائيًا التعليقات ومقاطع الأنماط. أدخل Sketch &quot;تفكير المكونات&quot; في سير عمل التصميم. لكنه لا يزال تطبيق سطح مكتب قائم على الملفات المحلية، ويتطلب التعاون في الوقت الفعلي استخدام أقراص الشبكة أو المكونات الإضافية الخارجية أو أدوات الإصدارات لتحقيقه بشكل غير مباشر، ولم يحل المشكلة الأساسية لـ &quot;عدة أشخاص يعدلون نفس المسودة في نفس الوقت&quot;.</p><p><img src="'+h+'" alt=""></p><p>ما غير قواعد اللعبة حقًا كان Figma. منذ عام 2016، دمج تصميم UI والنماذج الأولية والتعليقات التعاونية في المتصفح، ودعم ميزات حديثة متعددة: مؤشرات متعددة في الوقت الفعلي، تعليقات عبر الإنترنت، خط زمني للإصدارات، روابط مشاركة، إلخ. ما يبدو بسيطًا جدًا اليوم كان في ذلك الوقت تحديًا مباشرًا لنموذج Photoshop/Sketch.</p><p><img src="'+_+'" alt=""></p><p>بعد ذلك، لم يعد تصميم الواجهات ملفات مبعثرة على أجهزة الكمبيوتر الخاصة بكل شخص، بل مركزًا على لوحة عمل سحابية عبر الإنترنت ومحدثة في الوقت الفعلي. حول هذه اللوحة، يمكننا تخيل المزيد، باستخدام الأتمتة أو AI لطمس الحدود بين التصميم والكود الأمامي.</p><p>في البداية، لم نتمكن من الاعتماد إلا على مكونات إضافية من منصات مختلفة لتصدير المكونات ومعلومات الأنماط من التصميم شبه تلقائيًا كقصاصات كود (مثل هياكل مكونات React/Vue، متغيرات CSS، إلخ)، وجوهرها هو تحقيق استخراج المعلومات المنظمة من خلال المكونات الإضافية. بعد ذلك، مع تطور قدرات المنصة، بدأت معظم منصات التصميم في دعم وظائف MCP للنماذج الكبيرة (Model Context Protocol، بروتوكول سياق النموذج): يوفر هذا البروتوكول مجموعة من الآليات المعيارية التي تسمح للنماذج الكبيرة بالوصول بأمان وتحكم إلى ملفات التصميم وواجهات المكونات الإضافية والبيانات الوصفية للمشروع، مما يسهل تصدير التصميم ككود.</p><p>لاحقًا، على أساس المكونات الإضافية و MCP، دخلت أتمتة الكود الأمامي مرحلة دعم أصلي لاستنتاج هيكل الكود مباشرة من التصميم. يمكننا إنشاء هيكل مشروع واجهة أمامية كامل والتسلسل الهرمي للمكونات ونظام الأنماط ونتائج الكود المقابلة بنقرة واحدة داخل أداة التصميم. هذا يحرر المصممين ومهندسي تطوير الواجهة الأمامية من العمل اليدوي لنقل تفاصيل التصميم، ويسمح لهم بتخصيص مزيد من الجهد لتحسين تجربة المستخدم وتحديث إصدارات الوظائف.</p><hr><h2 id="_2-الشروع-في-figma" tabindex="-1">2. الشروع في Figma <a class="header-anchor" href="#_2-الشروع-في-figma" aria-label="Permalink to “2. الشروع في Figma”">​</a></h2><p>بعد ذلك ننتقل من المفاهيم المجردة إلى التطبيق العملي. نظرًا لقيود الوقت، سنتعلم فقط العمليات الأساسية لـ Figma لضمان أنه حتى لو لم تكن قد استخدمت أداة تصميم من قبل، يمكنك متابعة التمارين. إذا كنت ترغب في تعلم وظائف Figma الكاملة، يرجى الرجوع إلى الدروس الرسمية التفصيلية التي يوفرها Figma: <a href="https://help.figma.com/hc/en-us/sections/30880632542743-Figma-Design-for-beginners" target="_blank" rel="noreferrer">https://help.figma.com/hc/en-us/sections/30880632542743-Figma-Design-for-beginners</a></p><p>أو يمكنك الرجوع إلى الدروس التالية لبناء صفحة ويب بسيطة مثل معرض الأعمال الشخصي بسرعة: <a href="https://help.figma.com/hc/en-us/sections/35895585621655-Figma-Sites-collectio" target="_blank" rel="noreferrer">https://help.figma.com/hc/en-us/sections/35895585621655-Figma-Sites-collectio</a></p><p><img src="'+u+'" alt=""></p><p>على اليسار مدخل إنشاء المشاريع وإدارة الموارد، والأزرار في الزاوية العلوية اليمنى هي الوظائف الشائعة في Figma. من بينها، Make يُستخدم لجعل AI ينشئ لك مسودة واجهة أو هيكل تقريبي بجملة واحدة، Design هي منطقة العمل الرئيسية لرسم صفحات الويب/التطبيقات وبناء المكونات وإنشاء النماذج الأولية، FigJam مثل السبورة الجماعية، تُستخدم للصق الملاحظات اللاصقة ورسم المخططات الانسيابية والمناقشات الأولية، Buzz هي أداة إنتاج أصول العلامة التجارية على نطاق واسع، تُستخدم لإنشاء المحتوى دفعة واحدة للحفاظ على اتساق العلامة التجارية، و Site هي لتنظيم هذه التصاميم في صفحات ويب أو مواقع توثيق حقيقية قابلة للوصول للعرض الخارجي.</p><p>قد يبدو أن Figma لديه الكثير من الوظائف وأنه من الصعب البدء، لكن في الواقع هذه الأدوات الوظيفية هي في جوهرها مسألة تدريب وممارسة. لا تخف من ارتكاب أخطاء في البداية، ولا تفكر في القيام بكل شيء بشكل صحيح من المرة الأولى. فقط ابدأ في اللعب، وبالممارسة ستتمكن من الإتقان بسرعة.</p><p>في هذا الدرس التعليمي، للبدء بسرعة، سنقدم شرحًا بسيطًا لوظيفة Design.</p><h3 id="_2-1-إنشاء-ملف-design-جديد" tabindex="-1">2.1 إنشاء ملف Design جديد <a class="header-anchor" href="#_2-1-إنشاء-ملف-design-جديد" aria-label="Permalink to “2.1 إنشاء ملف Design جديد”">​</a></h3><p>من الصفحة الرئيسية أو المدخل في الزاوية العلوية اليمنى، اختر <strong>Design</strong> لإنشاء ملف جديد، وستدخل لوحة تصميم فارغة. تنقسم هذه الواجهة تقريبًا إلى ثلاثة أجزاء: على اليسار الصفحات والطبقات، تُستخدم لعرض وتعديل علاقة الصفحات والعناصر؛ في المنتصف لوحة العمل، لعرض التأثير الحالي؛ على اليمين الخصائص والأنماط، لتعديل الأشكال والألوان والأنماط المحددة؛ في الأسفل شريط أدوات، للتبديل بين الأدوات، بما في ذلك التحديد ورسم الأشكال وإدخال النص والتعليقات والمكونات الإضافية، إلخ. بعد تحديد أداة، يمكنك الضغط على مفتاح Esc للعودة إلى أداة الماوس الافتراضية.</p><p><img src="'+F+'" alt=""></p><h3 id="_2-2-إنشاء-إطارك-الأول-frame" tabindex="-1">2.2 إنشاء إطارك الأول (Frame) <a class="header-anchor" href="#_2-2-إنشاء-إطارك-الأول-frame" aria-label="Permalink to “2.2 إنشاء إطارك الأول (Frame)”">​</a></h3><p>قبل وضع العناصر رسميًا، تحتاج إلى تحديد حد واضح للصفحة أولاً، وهذا الحد يتولاه Frame. يمكنك اختيار أداة Frame من شريط الأدوات السفلي، أو الضغط مباشرة على مفتاح F، ثم سحب منطقة مستطيلة على لوحة العمل.</p><ol><li>استخدم أداة Frame من شريط الأدوات السفلي، أو اضغط مباشرة على مفتاح <code>F</code>.</li><li>اسحب منطقة مستطيلة في لوحة العمل، وغيّر العرض في شريط الخصائص الأيمن إلى مثلاً <code>1440</code>، والارتفاع إلى <code>900</code>.</li><li>في شريط الطبقات الأيسر، أعد تسمية هذا Frame، مثل <code>My First Page</code> أو اسم مشروعك.</li></ol><p>هذا Frame هو حاوية صفحة لواجهة شاشة واحدة. بعد ذلك، يجب وضع العنوان والنص والأزرار والصور والمحتويات الأخرى داخل هذا Frame، بدلاً من تناثرها في أي مكان على لوحة العمل. تنظيم المحتوى بحدود Frame يساعد في الحفاظ على هيكل قابل للتحكم عند إعداد التمرير لاحقًا، والتكيف مع أحجام الأجهزة المختلفة، وتصدير الشاشات وإنشاء النماذج الأولية.</p><p><img src="'+f+'" alt=""></p><h3 id="_2-3-وضع-النص-والعناصر-البسيطة-في-frame" tabindex="-1">2.3 وضع النص والعناصر البسيطة في Frame <a class="header-anchor" href="#_2-3-وضع-النص-والعناصر-البسيطة-في-frame" aria-label="Permalink to “2.3 وضع النص والعناصر البسيطة في Frame”">​</a></h3><p>الآن بعد أن أصبح لدينا حاوية، دعنا نتعلم كيفية وضع المكونات الأساسية، مثل: العنوان والعنوان الفرعي والزر ومنطقة الصورة الموضعية.</p><ol><li>اختر أداة النص (<code>T</code> في شريط الأدوات السفلي)، انقر في Frame، وأدخل عنوان الصفحة، مثل: <code>My Portfolio</code>. في الخصائص على اليمين، زِد حجم الخط قليلاً (مثلاً 96)، واجعل وزن الخط أثقل.</li><li>تحت العنوان، استخدم أداة النص مرة أخرى لإدخال سطر وصف بسيط، مثل جملة أو جملتين تصف ما تفعله هذه الصفحة. يمكن أن يكون حجم الخط أصغر قليلاً، وارتفاع السطر أكبر قليلاً، ليكون أسهل في القراءة.</li><li>ارسم شكل زر أولي: استخدم أداة المستطيل لرسم مستطيل بحجم <code>200 × 48</code> تقريبًا تحت العنوان، أعطه لون تعبئة واضح على اليمين، وأضف حدودًا مستديرة بشكل مناسب. <img src="'+q+'" alt=""></li><li>ثم استخدم أداة النص لإدخال نص الزر فوق المستطيل، مثل <code>Get Started</code>، حدد المستطيل والنص معًا، واستخدم أداة المحاذاة العلوية لجعل النص في المنتصف أفقيًا وعموديًا.</li><li>على جانب الزر أو تحته، ارسم مستطيلًا رماديًا فاتحًا كبيرًا كـ &quot;منطقة صورة موضعية&quot;، يمكن استخدامه لاحقًا لوضع صور العرض.</li></ol><p>بعد الوصول إلى هنا، لديك بالفعل &quot;مسودة صفحة رئيسية&quot; بسيطة جدًا ولكن ذات هيكل كامل: عنوان، فقرة، زر، ومنطقة عرض رئيسية.</p><p><img src="'+b+'" alt=""></p><h3 id="_2-4-استخدام-auto-layout-لتنظيم-العناصر" tabindex="-1">2.4 استخدام Auto Layout لتنظيم العناصر <a class="header-anchor" href="#_2-4-استخدام-auto-layout-لتنظيم-العناصر" aria-label="Permalink to “2.4 استخدام Auto Layout لتنظيم العناصر”">​</a></h3><p>إذا تم سحب جميع العناصر بشكل عشوائي فقط، فستصبح الصفحة فوضوية قريبًا. مفهوم مهم جدًا في Figma هو <strong>Auto Layout</strong>، الذي يمكنه تحويل مجموعة من العناصر إلى حاوية ذات قواعد.</p><p><img src="'+A+'" alt=""></p><p>يمكنك تحديد &quot;العنوان الرئيسي + العنوان الفرعي + الزر&quot; الثلاثة، والنقر على <strong>Add Auto layout</strong> في شريط الخصائص الأيمن.</p><p>عندها سيتم تغليف هذه العناصر الثلاثة في حاوية واحدة، ويمكنك تعديل المعلمات على اليمين، وستتكيف عناصر التخطيط تلقائيًا وفقًا للمعلمات:</p><ul><li>هل يتم ترتيبها عموديًا أم أفقيًا.</li><li>ما هي المسافة بين العناصر.</li><li>كم هو الهامش الداخلي بين هذه الكتلة وحافة الحاوية (padding).</li></ul><p><img src="'+k+'" alt=""></p><p>وبالمثل، يمكن استخدام Auto Layout داخل الزر أيضًا، يمكننا تحقيق هذا التأثير: عندما أقوم بتعديل النص، سيتكيف طول الزر تلقائيًا.</p><p>حدد مستطيل خلفية الزر ونص الزر أولاً، أضف Auto Layout، لجعل هذين الشيئين &quot;حاوية زر&quot;. ثم حدد حاوية الزر هذه، واضبط العرض والارتفاع على <strong>Hug contents</strong>. بهذه الطريقة، سيبقى النص دائمًا في منتصف الزر، سواء كان النص أكثر أو أقل، سيتكيف عرض الزر تلقائيًا.</p><p><img src="'+M+'" alt=""></p><h3 id="_2-5-تحويل-الزر-إلى-مكون-قابل-لإعادة-الاستخدام" tabindex="-1">2.5 تحويل الزر إلى مكون قابل لإعادة الاستخدام <a class="header-anchor" href="#_2-5-تحويل-الزر-إلى-مكون-قابل-لإعادة-الاستخدام" aria-label="Permalink to “2.5 تحويل الزر إلى مكون قابل لإعادة الاستخدام”">​</a></h3><p>الآن سنتعلم مفهومًا جديدًا: المكونات. المكون يعني عنصرًا يمكن إعادة استخدامه مرارًا، مثل الزر، طالما أنك تتوقع أنك ستستخدمه مرارًا، يمكنك التفكير في جعله مكونًا. سنقوم بالعملية الأساسية للزر الذي أضفنا إليه Auto Layout للتو:</p><ol><li>حدد حاوية الزر بالكامل.</li><li>انقر بزر الماوس الأيمن واختر Create component (إنشاء مكون). <img src="'+P+'" alt=""></li></ol><p>بهذا الشكل، يتحول هذا الزر من مجموعة طبقات عادية إلى قالب مكون رئيسي. بعد ذلك، إذا كنت تحتاج إلى زر بنفس النمط في صفحات أو Frames أخرى، يمكنك سحبه مباشرة من لوحة Assets على اليسار لاستخدامه.</p><p><img src="'+E+'" alt=""></p><p>في هذا الوقت، جميع الأزرار المستخدمة هي نسخ متزامنة من هذا القالب. عندما تقوم بتعديل لون القالب أو حدوده المستديرة أو مسافاته، ستتحدث جميع النسخ تلقائيًا.</p><p><img src="'+S+'" alt=""></p><p>بعد ذلك، تكون قد أتقنت الاستخدام البسيط لـ Figma بشكل أولي. لا تحتاج إلى فهم جميع الوظائف من البداية، فقط اتبع الخطوات لإنشاء أول صفحة بسيطة، وتعرف على هذه العمليات الأساسية القليلة، ثم استكشف ببطء المزيد من القدرات في الدروس الرسمية. مع زيادة مرات الاستخدام، ستتمكن بالتأكيد من الإتقان.</p><hr><h2 id="_3-الشروع-في-mastergo" tabindex="-1">3. الشروع في MasterGo <a class="header-anchor" href="#_3-الشروع-في-mastergo" aria-label="Permalink to “3. الشروع في MasterGo”">​</a></h2><p>بعد فهم سير العمل الأساسي لـ Figma، دعنا نلقي نظرة على MasterGo. يمكنك اعتبار MasterGo ببساطة كنسخة صينية من Figma، لكن مع بعض الاختلافات في بعض الوظائف. بشكل عام، يحافظ على تخطيط الواجهة وفلسفة التشغيل المشابهة لـ Figma: يحتوي أيضًا على لوحة عمل وشجرة طبقات ولوحة خصائص، ويدعم أيضًا المكونات والأنماط والتخطيط التلقائي والتعاون بين عدة أشخاص. للمزيد من التفاصيل، يمكنك الرجوع إلى الدروس الرسمية لـ MasterGo: <a href="https://mastergo.com/tutorials/12?%E5%85%A8%E7%A8%8B%E9%AB%98%E8%83%BD%EF%BC%8CMasterGo%20%E6%9C%80%E5%AE%8C%E6%95%B4%E5%AE%9E%E7%94%A8%E6%95%99%E7%A8%8B%EF%BC%8C%E8%AE%A9%E4%BD%A0%E4%BB%8E%E9%9B%B6%E5%88%B0%E7%B2%BE%E9%80%9A%EF%BC%81" target="_blank" rel="noreferrer">https://mastergo.com/tutorials/12?全程高能，MasterGo 最完整实用教程，让你从零到精通！</a></p><h3 id="_3-1-إنشاء-ملف-تصميم-جديد" tabindex="-1">3.1 إنشاء ملف تصميم جديد <a class="header-anchor" href="#_3-1-إنشاء-ملف-تصميم-جديد" aria-label="Permalink to “3.1 إنشاء ملف تصميم جديد”">​</a></h3><ol><li><p><strong>الدخول إلى واجهة MasterGo</strong></p><ol><li>افتح موقع MasterGo الرسمي وسجل الدخول إلى حسابك.</li><li>بعد الدخول، سترى منطقة الصفحة الرئيسية المشابهة لـ &quot;قائمة الملفات/قائمة المشاريع&quot;، لإدارة ملفات التصميم الخاصة بك. <img src="'+G+'" alt=""></li></ol></li><li><p><strong>إنشاء ملف جديد</strong></p><ol><li>ابحث عن زر &quot;+ ملف تصميم&quot; في الزاوية العلوية اليمنى وانقر عليه، أو اختر استيراد ملفات مثل Figma.</li><li>بعد النقر، ستدخل لوحة عمل فارغة، وهذه هي مساحة عمل التصميم في MasterGo.</li></ol></li><li><p><strong>التعرف على مناطق الواجهة الأساسية</strong> بعد تعلم استخدام Figma، طريقة استخدام MasterGo مشابهة جدًا، وتنقسم بشكل أساسي إلى عدة مناطق:</p><p><img src="'+x+'" alt=""></p><ol><li>شريط الأدوات العلوي: يقع في أعلى لوحة العمل، على اليسار موقع الملف واسمه، في المنتصف صف من أزرار الأدوات الشائعة (تحديد، منطقة/لوحة، شكل، نص، تعليق، تعليقات، اختيار المكونات الإضافية وأدوات AI، إلخ)، على اليمين الأعضاء المتصلون حاليًا، مدخل المشاركة، وتكبير/تصغير لوحة العمل والتحكم في المعاينة.</li><li>اللوحة اليسرى: تنقسم بشكل أساسي إلى طبقات وموارد، وهي حاليًا في علامة الطبقات التبويب، ويمكنك رؤية قائمة الصفحات، وهيكل وترتيب جميع الطبقات تحت هذه الصفحة.</li><li>منطقة لوحة العمل الوسطى: منطقة العمل المحددة للرسم والتخطيط، جميع Frames والمكونات والأشكال ستعرض هنا.</li><li>لوحة الخصائص اليمنى: لعرض وتعديل خصائص الكائن المحدد، مثل الحجم والموضع والمحاذاة وتعبئة الخلفية والحدود والحدود المستديرة، إلخ. إذا لم يتم تحديد أي كائن، فستعرض إعدادات متعلقة بلوحة العمل، مثل لون خلفية لوحة العمل والتسميات وخيارات التصدير.</li></ol></li></ol><h3 id="_3-2-إنشاء-إطارك-الأول" tabindex="-1">3.2 إنشاء إطارك الأول <a class="header-anchor" href="#_3-2-إنشاء-إطارك-الأول" aria-label="Permalink to “3.2 إنشاء إطارك الأول”">​</a></h3><p>قبل وضع الأشياء رسميًا، نحتاج إلى حاوية صفحة لتحديد حدود وأبعاد الواجهة. تسمى هذه الحاوية عادةً Frame في MasterGo.</p><p><strong>الخطوات:</strong></p><ol><li><strong>اختيار أداة Frame</strong><ol><li>ابحث عن أداة Frame/لوحة في شريط الأدوات، انقر لاستخدام المعلمات المسبقة لإنشاء المحتوى مباشرة على اللوحة.</li><li>أو استخدم اختصار لوحة المفاتيح (عادةً <code>F</code>، إذا كان هناك اختلاف، فاعتمد على الواجهة الفعلية).</li></ol></li><li><strong>اسحب منطقة مستطيلة في لوحة العمل</strong><ol><li>بعد السحب، سترى منطقة بإطار تحديد.</li><li>في لوحة الخصائص اليمنى، يمكنك رؤية عرض وارتفاع هذا Frame.</li><li>غيّر العرض إلى مثلاً <code>1440</code>، والارتفاع إلى <code>900</code> (أحد الأحجام الشائعة لصفحة ويب بشاشة واحدة).</li></ol></li><li><strong>إعادة تسمية Frame</strong><ol><li>ابحث عن هذا Frame في لوحة الطبقات اليسرى.</li><li>انقر نقرًا مزدوجًا على الاسم، وغيّره إلى اسم مشروعك، مثل: <code>My First Page</code>، أو أي اسم صفحة تريده.</li></ol></li></ol><p><img src="'+B+'" alt=""></p><h3 id="_3-3-إنشاء-محتوى-اللوحة" tabindex="-1">3.3 إنشاء محتوى اللوحة <a class="header-anchor" href="#_3-3-إنشاء-محتوى-اللوحة" aria-label="Permalink to “3.3 إنشاء محتوى اللوحة”">​</a></h3><p>الآن بعد أن أصبح لدينا حاوية، باستخدام طرق مشابهة لما تعلمناه في Figma، يمكننا بسهولة الحصول على صفحة عرض مشابهة. (يمكنك محاولة نسخ عناصر النص من لوحة Figma، ويدعم الاستيراد المباشر لمكونات النص عن طريق اللصق)</p><p><img src="'+C+'" alt=""></p><p>تجدر الإشارة إلى أن سلوك وظيفة Auto Layout مختلف قليلاً. في MasterGo، إذا كنت تريد تحقيق تأثير مشابه لـ Figma حيث يتغير طول الزر مع طول النص، تحتاج أولاً إلى إنشاء حاوية أو مكون على أساس عنصر المستطيل المقابل، كما هو موضح في الشكل:</p><p><img src="'+I+'" alt=""></p><p>بعد إنشاء الحاوية بنجاح، ضع مستطيل الزر والنص في الحاوية المقابلة جنبًا إلى جنب، ثم ابحث عن زر Auto Layout على اليمين وقم بتفعيل الوظيفة التلقائية، ويمكنك تحقيق وظيفة تكييف عرض الزر مع طول النص بنجاح.</p><p><img src="'+y+'" alt=""></p><p><img src="'+D+'" alt=""></p><h3 id="_3-4-إنشاء-صفحة-بالذكاء-الاصطناعي" tabindex="-1">3.4 إنشاء صفحة بالذكاء الاصطناعي <a class="header-anchor" href="#_3-4-إنشاء-صفحة-بالذكاء-الاصطناعي" aria-label="Permalink to “3.4 إنشاء صفحة بالذكاء الاصطناعي”">​</a></h3><p><img src="'+L+'" alt=""></p><p>في MasterGo، واحدة من الوظائف المثيرة للاهتمام التي تستحق الذكر هي إنشاء الصفحات بالذكاء الاصطناعي. يمكنك استخدام جملة واحدة أو إرفاق صورة مرجعية لإنشاء مكونات قابلة للتعديل في MasterGo والحصول على كود قابل للاستخدام مباشرة. يمكنك إدخال المتطلبات باللغة الصينية أو الإنجليزية مباشرة، وستقوم الصفحة بإرجاع مستند تخطيط صفحة بهيكل واضح وفقًا للمتطلبات، والتأثير كالتالي:</p><p><img src="'+v+'" alt=""></p><p><img src="'+T+'" alt=""></p><p>بعد انتهاء إنشاء مستند التصميم، انقر لبدء الإنشاء، وانتظر قليلاً للحصول على تأثير صفحة الويب الفعلية:</p><p><img src="'+J+'" alt=""></p><p>في هذا الوقت لديك خياران للعمل: الأول هو النقر على الزر الأزرق لإدراج نتيجة الإنشاء مباشرة في لوحة العمل، والثاني هو النقر على وظيفة معاينة الكود للحصول على كود الصفحة الكاملة مباشرة، وواجهة التشغيل المحددة كالتالي:</p><p><img src="'+N+'" alt=""></p><p><img src="'+R+'" alt=""></p><p>بعد إدراج النتيجة في لوحة العمل، يمكنك أيضًا إجراء تعديلات أكثر دقة على التخطيط العام للصفحة وتفاصيل العناصر (مثل الخطوط والألوان والمسافات، إلخ) حتى يطابق التأثير النهائي توقعاتك بالكامل.</p><p><img src="'+H+'" alt=""></p><hr><h2 id="_4-الخطوة-التالية-من-النموذج-الأولي-إلى-الكود" tabindex="-1">4. الخطوة التالية: من النموذج الأولي إلى الكود <a class="header-anchor" href="#_4-الخطوة-التالية-من-النموذج-الأولي-إلى-الكود" aria-label="Permalink to “4. الخطوة التالية: من النموذج الأولي إلى الكود”">​</a></h2><p>في المحتوى السابق، تعلمنا العمليات الأساسية لـ Figma و MasterGo، ويمكننا إنشاء نماذج أولية للواجهة بهيكل كامل. الخطوة الحاسمة التالية هي: <strong>كيفية تحويل هذه التصاميم إلى كود واجهة أمامية يعمل فعليًا في المتصفح؟</strong></p><div class="tip custom-block"><p class="custom-block-title">📚 الدروس اللاحقة</p><p>للحصول على مقدمة مفصلة للطرق، يرجى الرجوع إلى <a href="./../design-to-code/">من النموذج الأولي للتصميم إلى كود المشروع</a>، حيث ستتعلم:</p><ul><li><strong>التحويل المباشر بواسطة AI متعدد الوسائط</strong>: إرسال لقطات شاشة التصميم إلى AI لإنشاء كود HTML/React مباشرة</li><li><strong>Figma Make</strong>: استخدام أداة AI الرسمية من Figma لاستعادة التصميم بدقة عالية وتصدير الكود</li><li><strong>MasterGo AI</strong>: إنشاء صفحات قابلة للتعديل بنقرة واحدة والحصول على الكود</li></ul><p>لكل من هذه الطرق مزايا وعيوب، ومناسبة لسيناريوهات مختلفة. يُنصح باختيار سير العمل المناسب وفقًا لمتطلبات المشروع.</p></div><hr><h2 id="_5-الخلاصة" tabindex="-1">5. الخلاصة <a class="header-anchor" href="#_5-الخلاصة" aria-label="Permalink to “5. الخلاصة”">​</a></h2><p>من خلال دراسة هذا الفصل، تكون قد أتقنت:</p><ol><li><p><strong>قيمة أدوات تصميم الواجهات الأمامية</strong>: فهم سبب الحاجة إلى أدوات التصميم وكيف تحل مشاكل توزيع المعلومات والتعاون الجماعي.</p></li><li><p><strong>العمليات الأساسية في Figma</strong>:</p><ul><li>إنشاء ملف Design وإطارات Frame</li><li>إضافة عناصر أساسية مثل النص والأشكال</li><li>استخدام Auto Layout لتحقيق تخطيط متكيف</li><li>إنشاء نظام مكونات قابل لإعادة الاستخدام</li></ul></li><li><p><strong>العمليات الأساسية في MasterGo</strong>:</p><ul><li>التعرف على تخطيط الواجهة المشابه لـ Figma</li><li>إنشاء Frame ومحتوى اللوحة الأساسي</li><li>استخدام وظيفة إنشاء الصفحات بالذكاء الاصطناعي لإنشاء نماذج أولية بسرعة</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">💡 الخطوة التالية</p><p>الآن بعد أن أتقنت أساسيات استخدام أدوات تصميم الواجهات الأمامية، يمكنك تجربة:</p><ul><li>تصميم صفحة معرض أعمال شخصية لنفسك</li><li>تصميم نماذج أولية للواجهة للمشاريع القادمة</li><li>تعلم <a href="./../design-to-code/">من النموذج الأولي للتصميم إلى كود المشروع</a> لتحويل التصاميم إلى كود قابل للتشغيل</li></ul><p>إذا كنت تعمل على مشروع <a href="./../hogwarts-portraits/">لنصنع صور هوجورتس معًا</a>، يمكنك تصميم نموذج أولي للواجهة أولاً، ثم تصدير الكود ودمجه مع وظائف AI.</p></div>',112)),V(t,{title:"مقالات ذات صلة",description:"يُنصح بمواصلة تعميق تصميم UI والتمرين العملي على تحويل التصميم إلى كود.",items:w(i)},null,8,["items"])])}}});export{Z as __pageData,Q as default};
